<div class="row g-4 legal-fees-calculator-rebuilt"><div class="col-lg-12"><div class="calculator-card"><div class="calculator-body"><div class="row g-3"><div class="col-md-6"><label class="form-label-custom">Hourly Rate ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="lf-hourly" class="form-control form-control-lg" value="300" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Estimated Hours</label><div class="input-group"><input type="number" id="lf-hours" class="form-control form-control-lg" value="20" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Flat Fee ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="lf-flat" class="form-control form-control-lg" value="5000" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Monthly Retainer ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="lf-retainer" class="form-control form-control-lg" value="2000" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Retainer Months</label><div class="input-group"><input type="number" id="lf-months" class="form-control form-control-lg" value="6" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Contingency (%)</label><div class="input-group"><input type="number" id="lf-conting" class="form-control form-control-lg" value="33" min="0"><span class="input-group-text bg-light fw-bold">%</span></div></div></div></div></div></div><div class="col-lg-12"><div class="output-card-themed" style="--tool-hue:220;--tool-color:#64748b;--tool-bg:rgba(0,0,0,.02);"><div class="output-hero"><span class="output-hero-label">Legal Fees Calculator</span><div class="output-hero-value" id="legal-val">—</div><span class="output-hero-unit" id="legal-st">—</span></div><div class="row g-3 mt-3"><div class="col-md-3"><div class="stat-card" style="border-color:#64748b;background:rgba(0,0,0,.02);"><span class="stat-card-label">HOURLY COST</span><span class="stat-card-value" style="color:#64748b" id="lf-hcost">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#3b82f6;background:rgba(0,0,0,.02);"><span class="stat-card-label">RETAINER COST</span><span class="stat-card-value" style="color:#3b82f6" id="lf-rcost">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#22c55e;background:rgba(0,0,0,.02);"><span class="stat-card-label">TOTAL EST</span><span class="stat-card-value" style="color:#22c55e" id="lf-total">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#f59e0b;background:rgba(0,0,0,.02);"><span class="stat-card-label">BEST VALUE</span><span class="stat-card-value" style="color:#f59e0b" id="lf-best">—</span></div></div></div><div class="mt-4" id="legal-ins"></div><div class="row g-2 mt-4"><div class="col-md-4"><button class="btn d-block mx-auto btn-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="legal-cp"><i class="fas fa-copy me-2"></i>Copy Summary</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="legal-rs"><i class="fas fa-rotate-left me-2"></i>Reset</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-primary py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="legal-cb"><i class="fas fa-calculator me-2"></i>Calculate</button></div></div></div></div></div>
<script>document.addEventListener("DOMContentLoaded",function(){const $=id=>document.getElementById(id);function fmt(v){return"$"+Math.round(v).toLocaleString();}function calc(){const hr=parseFloat($("lf-hourly").value)||0,hrs=parseFloat($("lf-hours").value)||0,flat=parseFloat($("lf-flat").value)||0,ret=parseFloat($("lf-retainer").value)||0,mo=parseFloat($("lf-months").value)||0,ct=(parseFloat($("lf-conting").value)||0)/100;const hc=hr*hrs,rc=ret*mo,costs=[{n:"Hourly",v:hc},{n:"Flat",v:flat},{n:"Retainer",v:rc}].sort((a,b)=>a.v-b.v);const best=costs[0];$("legal-val").textContent=fmt(hc);$("lf-hcost").textContent=fmt(hc);$("lf-rcost").textContent=fmt(rc);$("lf-total").textContent=fmt(hc+flat);$("lf-best").textContent=best.n;$("legal-st").textContent="FEE ESTIMATE";$("legal-st").style.color="#64748b";let ins=[];ins.push("Hourly: <strong>"+fmt(hc)+"</strong>. Retainer: <strong>"+fmt(rc)+"</strong>. Flat: <strong>"+fmt(flat)+"</strong>.");ins.push("Best value option: <strong>"+best.n+"</strong> at "+fmt(best.v)+".");$("legal-ins").innerHTML='<h6 class="fw-bold mb-2"><i class="fas fa-lightbulb me-2 text-warning"></i>Analysis</h6><ul class="list-unstyled mb-0 small">'+ins.map(x=>'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+'</li>').join("")+'</ul>';}['lf-hourly','lf-hours','lf-flat','lf-retainer','lf-months','lf-conting'].forEach(id=>$(id).addEventListener("input",calc));$("legal-cb").addEventListener("click",calc);$("legal-cp").addEventListener("click",function(){navigator.clipboard.writeText("Legal Fees Calculator: "+$("legal-val").textContent).then(()=>{const o=this.innerHTML;this.innerHTML='<i class="fas fa-check me-2"></i>Copied!';setTimeout(()=>this.innerHTML=o,2e3);});});$("legal-rs").addEventListener("click",()=>{$("lf-hourly").value=300;$("lf-hours").value=20;$("lf-flat").value=5000;$("lf-retainer").value=2000;$("lf-months").value=6;$("lf-conting").value=33;calc();});calc();});</script>
<style>.legal-fees-calculator-rebuilt .calculator-card{background:#fff;border:1px solid #e5e7eb;border-radius:20px;padding:2rem;box-shadow:0 4px 24px rgba(0,0,0,.04)}.legal-fees-calculator-rebuilt .calculator-header{display:flex;align-items:center;gap:1.25rem;margin-bottom:2rem}.legal-fees-calculator-rebuilt .calculator-header h4{margin:0;font-weight:700;font-size:1.1rem;color:#1e293b}.legal-fees-calculator-rebuilt .calculator-header p{margin:0;font-size:.85rem;color:#64748b}.legal-fees-calculator-rebuilt .tool-icon-circle{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.4rem;flex-shrink:0}.legal-fees-calculator-rebuilt .form-label-custom{font-size:.75rem;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.8px;margin-bottom:.4rem;display:block}</style><?php /**PATH D:\Xamp\htdocs\ToolsHub\resources\views\tools\interactive\legal-fees-calculator.blade.php ENDPATH**/ ?>